for(const width of [320,390,768,1440,1920])test('compact grouped exams: readable controls, all fields visible and narrower cards '+width,async()=>{
 const p=await page(width);await begin(p);await p.locator('[data-condition=ckd]').uncheck();await p.locator('[data-condition=diabetes]').check();
 for(const name of ['glucose','fructosamine','bhb','creatinine','bun','usg','cholesterol','alt'])assert.equal(await p.locator('[data-field="measurements.'+name+'"]').isVisible(),true,name);
 assert.equal(await p.locator('[data-exam-group=blood] [data-field="measurements.glucose"]').count(),1);assert.equal(await p.locator('[data-exam-group=urine] [data-field="measurements.usg"]').count(),1);
 assert.equal(await p.locator('[data-exam-group=basic] [data-field="symptoms.appetite"]').count(),1);
 const cards=await p.locator('[data-exam-group=blood] .chr-value-wrap').evaluateAll(es=>es.map(e=>{const r=e.getBoundingClientRect();return {x:r.x,y:r.y,w:r.width};}));if(width>=1440){assert.ok(cards[0].w<=230);assert.ok(cards.filter(r=>Math.abs(r.y-cards[0].y)<2).length>=6);}
 assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),true);assert.equal(await p.locator('[data-field="measurements.glucose"]').inputValue(),'');await p.locator('[data-field="measurements.bhb"]').fill('0.4');await save(p);await p.reload();await p.locator('[data-field="measurements.bhb"]').waitFor();assert.equal(await p.locator('[data-field="measurements.bhb"]').inputValue(),'0.4');
 if(process.env.CHR_SHOTS){fs.mkdirSync(process.env.CHR_SHOTS,{recursive:true});await p.locator('[data-panel=exam]').screenshot({path:path.join(process.env.CHR_SHOTS,'compact-group-'+width+'.png')});}await p.close();
});
