const harness=`<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/practice-tools.css"><link rel="stylesheet" href="/neuro-record.css"><link rel="stylesheet" href="/ophthalmic-record.css"><link rel="stylesheet" href="/chronic-record.css"><style>@font-face{font-family:Pretendard;src:url(/pretendard-variable-1.3.9.woff2)}body{font-family:Pretendard,sans-serif;margin:14px;background:#f5f7fb}</style><main id="root"></main><script src="/ophthalmic-record.js"></script><script src="/chronic-record.js"></script><script>
window.state={scope:'test:owner',canEdit:true,records:JSON.parse(sessionStorage.getItem('mock-records')||'[]'),requests:[],keys:{},imageData:{},fail:false};
const patient={id:'p1',name:'합성 환자',species:'dog',breed:'합성 품종',sex:'male',neutered:'yes',birthDate:'2020-01-01',latestWeightKg:5,guardianName:'합성 보호자',chartNumber:'TEST-101'};
const persist=()=>sessionStorage.setItem('mock-records',JSON.stringify(state.records));
function images(d,id,revision){for(const im of d.images){if(im.dataUrl){state.imageData[id+':'+im.id]=im.dataUrl;delete im.dataUrl;im.imageRevision=revision;}}return d;}
window.api=async(p,o={})=>{state.requests.push({p,...o});if(state.fail)throw Error('합성 네트워크 실패');if(p.startsWith('/patient-directory'))return {patients:[patient],pagination:{hasNext:false}};if(p.endsWith('/members'))return {members:[{id:'u',display_name:'시험 검사자'}]};const b=o.body?JSON.parse(o.body):null;if(p.endsWith('/workflows')){state.workflows??=[];if(o.method==='POST'){const w={id:'w'+state.workflows.length,body:b.body};state.workflows.push(w);return {ok:true,id:w.id};}return {items:state.workflows};}
if(p.includes('/chronic-context?')&&state.contextPages)return state.contextPages[new URL('https://test'+p).searchParams.get('cursor')||'first'];if(p.includes('/chronic-context?'))return {items:state.records.filter(r=>!r.body.deleted).map(r=>({id:r.id,category:'chronic',title:'만성질환 기록',date:r.body.chronicChart.date,chart:structuredClone(r.body.chronicChart),medications:r.body.chronicChart.medications,images:r.body.chronicChart.images})),hasMore:false};if(p.includes('/chronic?')){const q=new URL('https://test'+p).searchParams;if(state.pages)return state.pages[q.get('cursor')||'first'];return {items:state.records.filter(r=>!r.body.deleted&&(!q.get('patientId')||r.patient_id===q.get('patientId'))&&(!q.get('status')||r.body.chronicChart.clinicalStatus===q.get('status'))&&(!q.get('q')||(r.patient.name+r.body.chronicChart.diagnosis).includes(q.get('q')))).map(r=>({id:r.id,patientId:r.patient_id,conditions:r.body.chronicChart.conditions,time:r.body.chronicChart.time,patient:{...r.patient,...r.body.chronicChart.patient},date:r.body.chronicChart.date,diagnosis:r.body.chronicChart.diagnosis,clinicalStatus:r.body.chronicChart.clinicalStatus})),next:null};}
if(b?.requestKey&&state.keys[b.requestKey])return {...state.keys[b.requestKey],replayed:true};
if(p.endsWith('/cases')&&o.method==='POST'){const r={id:'e'+(state.records.length+1),revision:1,patient_id:b.patientId||'',patient:b.patientId?patient:{...b.quickPatient,species:b.species},body:{species:b.species,category:'chronic',previousId:b.previousId,chronicChart:images(structuredClone(b.chronicChart),'e'+(state.records.length+1),1)}};state.records.push(r);persist();const out={id:r.id,revision:1,chronicChart:structuredClone(r.body.chronicChart)};state.keys[b.requestKey]=out;if(state.loseResponse){state.loseResponse=false;throw Error('합성 응답 유실');}return out;}
const id=p.split('/cases/')[1]?.split(/[/?]/)[0],r=state.records.find(x=>x.id===id);if(!r||r.body.deleted)throw Error('기록 없음');if(o.method==='POST'){if(b.revision!==r.revision)throw Object.assign(Error('다른 직원이 기록했습니다.'),{status:409});if(b.kind==='case.delete')r.body.deleted=true;else {if(r.body.chronicChart.clinicalStatus==='complete'&&b.data.clinicalStatus==='complete'&&JSON.stringify(r.body.chronicChart)!==JSON.stringify(b.data))b.data.clinicalStatus='amended';r.body.chronicChart=images(structuredClone(b.data),id,r.revision+1);}r.revision++;persist();const out={id:r.id,revision:r.revision,chronicChart:structuredClone(r.body.chronicChart)};state.keys[b.requestKey]=out;if(state.loseResponse){state.loseResponse=false;throw Error('합성 응답 유실');}return out;}
if(p.includes('/chronic-images'))return {dataUrl:state.imageData[id+':'+new URL('https://test'+p).searchParams.get('id')]};return {item:structuredClone(r),canManage:state.canEdit};};
window.opts={ready:()=>true,identity:()=>state.scope,can:k=>k!=='records.edit'||state.canEdit,medical:()=>state.canEdit,clinicalManage:()=>state.canEdit,request:(p,o)=>api(p,o),clinicName:()=> '합성 시험 병원'};window.view=ChronicRecord.mount(document.querySelector('#root'),opts);view.open();</script>`;
before(async()=>{server=http.createServer((req,res)=>{const name=new URL(req.url,'http://local').pathname.slice(1);if(!name){res.setHeader('Content-Type','text/html; charset=utf-8');res.end(harness);return;}const file=path.join(root,name);if(!fs.existsSync(file)){res.writeHead(404);res.end();return;}res.setHeader('Content-Type',name.endsWith('.html')?'text/html; charset=utf-8':name.endsWith('.css')?'text/css':name.endsWith('.woff2')?'font/woff2':'application/javascript');res.end(fs.readFileSync(file));});await new Promise(r=>server.listen(0,'127.0.0.1',r));url='http://127.0.0.1:'+server.address().port;browser=await chromium.launch({executablePath:process.env.HQ_TEST_BROWSER,headless:true});});
after(async()=>{await browser?.close();server.closeAllConnections();await new Promise(r=>server.close(r));});
test('rejected payload is replaced after correction without automatic rejection loops',async()=>{const p=await page();await begin(p);await p.evaluate(()=>{const old=window.api;state.rejections=[];window.api=async(path,o={})=>{const b=o.body?JSON.parse(o.body):null;if(b?.data?.stage==='reject'){state.rejections.push(b.requestKey);throw Object.assign(Error('단계 입력 확인'),{status:422});}return old(path,o);};});await section(p,'plan');await p.locator('[data-field=stage]').fill('reject');await p.locator('[data-act=save]').click();await p.locator('[data-status]').filter({hasText:'저장 실패'}).waitFor();await p.waitForTimeout(1700);assert.equal(await p.evaluate(()=>state.rejections.length),1);await p.locator('[data-field=stage]').fill('수정된 단계');await save(p);assert.equal(await p.evaluate(()=>state.records[0].body.chronicChart.stage),'수정된 단계');const sent=await p.evaluate(()=>state.requests.filter(x=>x.body&&JSON.parse(x.body).data?.stage==='수정된 단계').map(x=>JSON.parse(x.body).requestKey));assert.notEqual(sent[0],await p.evaluate(()=>state.rejections[0]));await p.close();});
test('future birth date is focused before any save and correction can save',async()=>{const p=await page();await quick(p);await p.locator('[data-field="patient.birthDate"]').fill('2099-01-01');await p.locator('[data-act=save]').click();assert.equal(await p.evaluate(()=>document.activeElement.dataset.field),'patient.birthDate');assert.equal(await p.locator('[data-field="patient.birthDate"]').getAttribute('aria-invalid'),'true');assert.equal(await p.evaluate(()=>state.records.length),0);await p.locator('[data-field="patient.birthDate"]').fill('2020-01-01');await save(p);assert.equal(await p.evaluate(()=>state.records[0].body.chronicChart.patient.birthDate),'2020-01-01');await p.close();});
test('selected visit refresh uses corrected values and clears deleted comparison',async()=>{const p=await page();await begin(p);await p.locator('[data-field="measurements.creatinine"]').fill('2.4');await save(p);await p.locator('[data-act=recheck]').click();await section(p,'compare');await p.locator('[data-compare-mode]').selectOption('visit');await p.locator('[data-compare]').selectOption('e1');await p.evaluate(()=>state.records[0].body.chronicChart.measurements.creatinine=3.6);await p.locator('[data-act=refresh-sources]').click();await p.waitForFunction(()=>document.querySelector('[data-comparison]').textContent.includes('3.6'));assert.doesNotMatch(await p.locator('[data-comparison]').innerText(),/2\.4/);await p.evaluate(()=>state.records[0].body.deleted=true);await p.locator('[data-act=refresh-sources]').click();await p.waitForFunction(()=>!document.querySelector('[data-comparison]').textContent.includes('3.6'));assert.match(await p.locator('[data-status]').innerText(),/삭제|제외/);await p.close();});
test('input unit is adjacent to value with no conflicting fixed unit',async()=>{const p=await page();await begin(p);await p.locator('[data-field="measurements.creatinine"]').fill('2');await p.locator('[data-unit=creatinine]').selectOption('µmol/L');assert.equal(await p.locator('[data-field="measurements.creatinine"]').inputValue(),'176.8');const card=p.locator('.chr-value').filter({has:p.locator('[data-unit=creatinine]')});assert.equal(await card.locator('.chr-fixed-unit').count(),0);assert.equal(await card.locator(':scope > span').first().innerText(),'크레아티닌 · Creatinine');assert.match(await card.locator('[data-canonical]').innerText(),/2 mg\/dL/);await save(p);await p.reload();await p.locator('[data-unit=creatinine]').waitFor();assert.equal(await p.locator('[data-unit=creatinine]').inputValue(),'µmol/L');await p.close();});
test('context methods are scoped and legacy methods are retained',async()=>{const p=await page();await begin(p);await p.locator('[data-condition=hypothyroid]').check();await p.locator('[data-condition=addison]').check();const options=k=>p.locator('[data-field="testContexts.'+k+'.method"] option').allTextContents();assert.deepEqual(await options('thyroid'),['선택','기저 검사','기타']);assert.deepEqual(await options('docp'),['선택','전해질 재검','기타']);assert.ok((await options('cortisol')).includes('ACTH 자극 검사'));await save(p);await p.evaluate(()=>{state.records[0].body.chronicChart.testContexts.thyroid.method='postDose';sessionStorage.setItem('mock-records',JSON.stringify(state.records));});await p.reload();await p.locator('[data-field="testContexts.thyroid.method"]').waitFor({state:'attached'});assert.equal(await p.locator('[data-field="testContexts.thyroid.method"]').inputValue(),'postDose');assert.ok((await options('thyroid')).includes('기존 선택 · 투약 후'));await p.close();});
test('trend identifies current and previous values and supports point keyboard activation',async()=>{const p=await page();await begin(p);await p.locator('[data-field="measurements.creatinine"]').fill('2');await save(p);await p.locator('[data-act=recheck]').click();await p.locator('[data-field="measurements.creatinine"]').fill('3');await section(p,'compare');await p.locator('[data-trend]').selectOption('creatinine');assert.match(await p.locator('.chr-trend-summary').innerText(),/이번 결과\s*3 mg\/dL[\s\S]*비교값\s*2 mg\/dL[\s\S]*\+1 mg\/dL/);assert.equal(await p.locator('[data-trend-point]').count(),2);await p.locator('[data-trend-point="0"]').focus();await p.keyboard.press('Enter');assert.match(await p.locator('[data-point-detail]').innerText(),/이전 결과.*2 mg\/dL/);await p.locator('[data-trend-point="1"]').click();assert.match(await p.locator('[data-point-detail]').innerText(),/이번 결과.*3 mg\/dL/);await p.close();});
for(const width of [390,768,1440])test('compact input and comparison layout '+width,async()=>{const p=await page(width);await begin(p);await p.locator('[data-field="measurements.creatinine"]').fill('2');await p.locator('[data-unit=creatinine]').selectOption('µmol/L');const boxes=await p.evaluate(()=>['[data-field="measurements.creatinine"]','[data-unit=creatinine]'].map(s=>{const b=document.querySelector(s).getBoundingClientRect();return {x:b.x,y:b.y,width:b.width,height:b.height,right:b.right};}));if(width>700){assert.ok(Math.abs(boxes[0].y-boxes[1].y)<2);assert.ok(boxes[0].right<=boxes[1].x);}else{assert.ok(boxes[1].y>=boxes[0].y+boxes[0].height);assert.ok(boxes[0].width>=100);}assert.ok(boxes.every(b=>b.width>=45&&b.height>=38));assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),true);if(process.env.CHR_SHOTS){fs.mkdirSync(process.env.CHR_SHOTS,{recursive:true});await p.screenshot({path:path.join(process.env.CHR_SHOTS,'entry-'+width+'.png'),fullPage:true});}await save(p);await p.locator('[data-act=recheck]').click();await p.locator('[data-field="measurements.creatinine"]').fill('3');await section(p,'compare');await p.locator('[data-trend]').selectOption('creatinine');assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),true);if(process.env.CHR_SHOTS)await p.screenshot({path:path.join(process.env.CHR_SHOTS,'compare-'+width+'.png'),fullPage:true});await p.close();});
async function page(width=1440){const p=await browser.newPage({viewport:{width,height:950}});p.setDefaultTimeout(7000);p.on('dialog',d=>d.accept());await p.goto(url);await p.locator('[data-act=new]').waitFor();return p;}
async function quick(p){await p.locator('[data-act=new]').click();await p.locator('[data-name]').fill('합성 만성환자');await p.locator('[data-species]').selectOption('cat');await p.locator('[data-field="patient.guardianName"]').fill('시험 보호자');await p.locator('[data-condition=ckd]').check();}
async function save(p){await p.locator('[data-act=save]').click();await p.waitForFunction(()=>document.querySelector('[data-act=save]')?.textContent==='저장됨'&&!document.querySelector('[data-act=save]').disabled);}
async function begin(p){await quick(p);await save(p);await p.locator(".chr-diseases").evaluate(e=>e.open=true);}
async function section(p,n){await p.locator('[data-section="'+n+'"]').click();}
test('registered patient identity is reused, fresh measurements remain empty',async()=>{const p=await page();await p.locator('[data-act=new]').click();await p.locator('[data-patient-query]').fill('합성');await p.locator('[data-patient-form] button').click();await p.locator('[data-pick="0"]').click();await p.locator('[data-condition=ckd]').check();assert.equal(await p.locator('[data-field="patient.breed"]').inputValue(),'합성 품종');assert.equal(await p.locator('[data-sex]').inputValue(),'male:yes');assert.equal(await p.locator('[data-field="weight"]').inputValue(),'');await save(p);assert.equal(await p.evaluate(()=>state.records[0].patient_id),'p1');await p.close();});
test('recheck never copies previous normals or measurements and compares values',async()=>{const p=await page();await begin(p);await p.locator('[data-field="measurements.creatinine"]').fill('2.4');await p.locator('[data-field="weight"]').fill('5');await p.locator('[data-field="symptoms.appetite"]').selectOption('usual');await save(p);await p.locator('[data-act=recheck]').click();assert.equal(await p.locator('[data-field="measurements.creatinine"]').inputValue(),'');assert.equal(await p.locator('[data-field="weight"]').inputValue(),'');assert.equal(await p.locator('[data-field="symptoms.appetite"]').inputValue(),'');assert.match(await p.locator('[data-prev=creatinine]').innerText(),/2.4 mg\/dL/);await p.locator('[data-field="measurements.creatinine"]').fill('2.7');await section(p,'compare');assert.match(await p.locator('[data-comparison]').innerText(),/2.4[\s\S]*2.7\s+\+0.3/);await save(p);assert.equal(await p.evaluate(()=>Object.keys(state.records[1].body.chronicChart.symptoms).length),0);await p.close();});
test('disease selection keeps entered results and all relevant exams visible',async()=>{const p=await page();await begin(p);await p.locator('[data-field="measurements.creatinine"]').fill('2.2');await p.locator('[data-condition=diabetes]').check();assert.equal(await p.locator('[data-field="measurements.glucose"]').count(),1);await p.locator('[data-field="measurements.glucose"]').fill('180');await p.locator('[data-condition=ckd]').uncheck();assert.equal(await p.locator('[data-field="measurements.creatinine"]').count(),1);assert.equal(await p.locator('[data-field="measurements.bhb"]').isVisible(),true);await save(p);assert.equal(await p.evaluate(()=>state.records[0].body.chronicChart.measurements.creatinine),2.2);await p.locator('[data-condition=ckd]').check();assert.equal(await p.locator('[data-field="measurements.creatinine"]').inputValue(),'2.2');await p.close();});
test('response loss retry does not duplicate visit or overwrite later edits',async()=>{const p=await page();await quick(p);await p.evaluate(()=>state.loseResponse=true);await p.locator('[data-act=save]').click();await p.locator('[data-status]').filter({hasText:'저장 실패'}).waitFor();await p.locator('[data-field="measurements.creatinine"]').fill('3.1');await save(p);await p.waitForFunction(()=>state.records[0].body.chronicChart.measurements.creatinine===3.1);assert.equal(await p.evaluate(()=>state.records.length),1);await p.close();});
test('concurrent changes preserve both staff inputs after explicit comparison',async()=>{const p=await page();await begin(p);await p.evaluate(()=>{state.records[0].revision++;state.records[0].body.chronicChart.measurements.creatinine=4;});await p.locator('[data-field="measurements.creatinine"]').fill('3');await p.locator('[data-act=save]').click();await p.locator('[data-act=resolve]').click();await p.locator('[data-choice]').selectOption('local');await p.locator('[data-merge]').click();await p.waitForFunction(()=>state.records[0].body.chronicChart.measurements.creatinine===3);await p.close();});
test('medication import is explicit and retains source/date without auto prescribing',async()=>{const p=await page();await begin(p);await section(p,'plan');await p.locator('[data-field=medications]').fill('원본 약물 1 mg PO');await save(p);await p.locator('[data-act=recheck]').click();await section(p,'plan');assert.equal(await p.locator('[data-field=medications]').inputValue(),'');await p.locator('[data-panel=plan] [data-act=sources]').click();await p.locator('[data-reuse-key=medications]').first().click();assert.match(await p.locator('[data-field=medications]').inputValue(),/원본 약물/s);await save(p);assert.equal(await p.evaluate(()=>state.requests.filter(r=>r.body?.includes('order.add')).length),0);await p.close();});
test('photos can be imported from prior visit and each visit keeps its own references',async()=>{const p=await page();await begin(p);await section(p,'photos');const data=await p.evaluate(()=>{const c=document.createElement('canvas');c.width=c.height=50;c.getContext('2d').fillRect(0,0,50,50);return c.toDataURL().split(',')[1];});await p.locator('[data-photo]').setInputFiles({name:'synthetic.png',mimeType:'image/png',buffer:Buffer.from(data,'base64')});await p.locator('[data-caption]').waitFor();await save(p);await p.locator('[data-act=recheck]').click();await section(p,'photos');await p.locator('[data-related] summary').click();await p.locator('[data-photo-source]').click();await p.locator('[data-import-photo]').click();await save(p);const ids=await p.evaluate(()=>state.records.map(r=>r.body.chronicChart.images[0].id));assert.notEqual(ids[0],ids[1]);await p.locator('[data-remove-photo]').click();await save(p);assert.equal(await p.evaluate(()=>state.records[0].body.chronicChart.images.length),1);await p.close();});
test('reload reopens saved patient and write permission is enforced',async()=>{const p=await page();await begin(p);await p.locator('[data-field="measurements.creatinine"]').fill('2');await save(p);await p.reload();await p.locator('[data-field="measurements.creatinine"]').waitFor();assert.equal(await p.locator('[data-field="measurements.creatinine"]').inputValue(),'2');await p.evaluate(async()=>{view.dispose();state.canEdit=false;view=ChronicRecord.mount(document.querySelector('#root'),opts);await view.open();});assert.equal(await p.locator('[data-act=save]').count(),0);assert.equal(await p.locator('[data-field="measurements.creatinine"]').isDisabled(),true);await p.evaluate(()=>{state.scope='other';view.sync();});assert.equal(await p.locator('#root').innerText(),'');await p.close();});
test('inpatient shortcut shares identity but no prior examination results',async()=>{const p=await page();await p.evaluate(()=>view.fromCase({id:'ward-test',patient_id:'p1',patient:{id:'p1',name:'입원 합성',breed:'시험 품종',sex:'female',neutered:'yes',birthDate:'2021-01-01'},body:{species:'dog',weight:6,patientDemographics:{breed:'시험 품종',sex:'female',neutered:'yes',birthDate:'2021-01-01'}}}));await p.locator('[data-field="weight"]').waitFor();assert.equal(await p.locator('[data-name]').inputValue(),'입원 합성');assert.equal(await p.locator('[data-field="weight"]').inputValue(),'');await p.locator('[data-condition=ckd]').check();await save(p);const req=await p.evaluate(()=>JSON.parse(state.requests.find(r=>r.body).body));assert.equal(req.linkedCaseId,'ward-test');assert.equal(req.patientId,'p1');await p.close();});
test('invalid ranges do not save, zero does not become missing',async()=>{const p=await page();await begin(p);await p.locator('[data-field="measurements.creatinine"]').fill('-1');await p.locator('[data-act=save]').click();assert.match(await p.locator('[data-status]').innerText(),/범위/);await p.locator('[data-field="measurements.creatinine"]').fill('0');await save(p);assert.equal(await p.evaluate(()=>state.records[0].body.chronicChart.measurements.creatinine),0);await p.close();});
test('print contains current and prior values plus escaped text and produces PDF',async()=>{const p=await page();await begin(p);await p.locator('[data-field="measurements.creatinine"]').fill('2.2');await section(p,'plan');await p.locator('[data-field=diagnosis]').fill('<script>window.injected=true</script>');await save(p);const waiting=p.waitForEvent('popup');await p.locator('[data-act=print]').click();const out=await waiting;await out.locator('h1').first().waitFor();await out.locator('input[type=checkbox]').first().check();assert.match(await out.locator('body').innerText(),/만성질환 진료 요약.*2.2/s);assert.equal(await out.evaluate(()=>window.injected),undefined);await out.waitForFunction(()=>[...document.fonts].some(f=>f.status==='loaded'));const pdf=await out.pdf({preferCSSPageSize:true});assert.ok(pdf.length>1000);if(process.env.CHR_SCREENSHOT_DIR)fs.writeFileSync(path.join(process.env.CHR_SCREENSHOT_DIR,'chronic-synthetic.pdf'),pdf);await out.close();await p.close();});
for(const width of [320,390,768,1440])test('responsive list, record and comparison fit '+width,async()=>{const p=await page(width);assert.ok(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));await begin(p);assert.ok(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));assert.ok(await p.locator('[data-panel=exam]').evaluate(e=>e.clientWidth>document.querySelector('#root').clientWidth*.9),'exam uses full available width');assert.ok(await p.locator('[data-field=weight]').evaluate(e=>e.clientWidth>85),'measurement is readable');for(const s of ['plan','compare','photos','exam']){await section(p,s);assert.ok(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),s);}if(process.env.CHR_SCREENSHOT_DIR)await p.screenshot({path:path.join(process.env.CHR_SCREENSHOT_DIR,'chronic-'+width+'.png'),fullPage:true});await p.close();});
test('actual menu routing restores list and saves before leaving',async()=>{const p=await page();await p.addScriptTag({url:url+'/practice-tools.js'});await p.evaluate(async()=>{view.dispose();window.practice=PracticeTools.mount(document.querySelector('#root'),{...opts,patient:()=>null,navigation:()=>{}});if(!practice.prepareTab('chronic'))throw Error('route');await practice.open();});await begin(p);await p.locator('[data-field="measurements.creatinine"]').fill('2.8');await p.evaluate(()=>{if(practice.prepareTab('intake',()=>practice.open()))void practice.open();});await p.waitForFunction(()=>practice.route()==='intake');assert.equal(await p.evaluate(()=>state.records[0].body.chronicChart.measurements.creatinine),2.8);await p.close();});

test('browser saves and rechecks against the actual encrypted server',async t=>{const {pathToFileURL}=require('node:url'),wr=process.env.TRAINING_WORKER_ROOT;if(!wr)throw Error('TRAINING_WORKER_ROOT required');const {fixture}=await import(pathToFileURL(path.join(wr,'test/helpers/practice-fixture.mjs')).href),f=fixture(t);f.c.structuredClone=structuredClone;f.c.atob=atob;f.sqlite.exec(fs.readFileSync(path.join(wr,'migrations/20261026_clinical_workspace.sql'),'utf8'));f.sqlite.exec("ALTER TABLE care_patients ADD COLUMN species TEXT DEFAULT 'dog'");const p=await page();await p.route('**/test-api/**',async route=>{const req=route.request(),u=new URL(req.url());try{const out=await f.extras(u.pathname.replace('/test-api/practice','')+u.search,req.method(),req.postDataJSON()||{},f.owner);await route.fulfill({json:out});}catch(e){await route.fulfill({status:e.statusCode||500,json:{error:e.message}});}});await p.evaluate(()=>{api=async(p,o={})=>{const r=await fetch('/test-api'+p,o),d=await r.json();if(!r.ok)throw Object.assign(Error(d.error),{status:r.status});return d;};});await quick(p);await p.locator('[data-field="measurements.creatinine"]').fill('2.3');await p.locator('[data-field="symptoms.appetite"]').selectOption('usual');await section(p,'plan');await p.locator('[data-field=medications]').fill('합성 약물 확인 기록');await p.locator('[data-condition=cardiac]').check();await p.locator('[data-condition=imha]').check();await p.locator('[data-condition=ple]').check();await section(p,'exam');await p.locator('[data-panel=exam] details').evaluateAll(es=>es.forEach(e=>e.open=true));await p.locator('[data-field="measurements.ntproBNP"]').fill('1234');await p.locator('[data-field="measurements.ctni"]').fill('0.026');await p.locator('[data-field="measurements.reticulocytes"]').fill('95.5');await p.locator('[data-field="measurements.cortisolBaseline"]').fill('2.8');await p.locator('[data-field="examNotes.diseaseActivity"]').fill('사용 지표·점수 확인');await section(p,'photos');const data=await p.evaluate(()=>{const c=document.createElement('canvas');c.width=c.height=50;return c.toDataURL().split(',')[1];});await p.locator('[data-photo]').setInputFiles({name:'synthetic.png',mimeType:'image/png',buffer:Buffer.from(data,'base64')});await p.locator('[data-caption]').waitFor();await save(p);const list=await f.extras('/clinical/chronic','GET',{},f.owner);assert.equal(list.items.length,1);const id=list.items[0].id,record=await f.extras('/clinical/cases/'+id+'?view=chronic','GET',{},f.owner);assert.equal(record.item.body.chronicChart.measurements.creatinine,2.3);assert.equal(record.item.body.chronicChart.measurements.ntproBNP,1234);assert.equal(record.item.body.chronicChart.measurements.ctni,0.026);assert.equal(record.item.body.chronicChart.measurements.reticulocytes,95.5);assert.equal(record.item.body.chronicChart.measurements.cortisolBaseline,2.8);assert.equal(record.item.body.chronicChart.examNotes.diseaseActivity,'사용 지표·점수 확인');assert.equal(record.item.body.chronicChart.images[0].imageRevision,1);await p.locator('[data-act=back]').click();await p.locator('[data-open]').click();await section(p,'photos');await p.waitForFunction(()=>document.querySelector('[data-image-id]')?.naturalWidth>0);await p.locator('[data-act=recheck]').click();assert.equal(await p.locator('[data-field="measurements.creatinine"]').inputValue(),'');assert.equal(await p.locator('[data-field="symptoms.appetite"]').inputValue(),'');await save(p);assert.equal((await f.extras('/clinical/chronic','GET',{},f.owner)).items.length,2);await p.close();});

