test('cardiac markers show units, preserve decimals, compare previous visit and print',async()=>{const p=await page();await begin(p);await p.locator('[data-condition=cardiac]').check();assert.equal(await p.locator('[data-field="measurements.ntproBNP"]').isVisible(),true);await p.locator('[data-panel=exam] details').first().locator('summary').click();assert.match(await p.locator('[data-field="measurements.ntproBNP"]').locator('..').innerText(),/pmol\/L/);assert.match(await p.locator('[data-field="measurements.ctni"]').locator('..').innerText(),/ng\/mL/);await p.locator('[data-panel=exam] details').evaluateAll(es=>es.forEach(e=>e.open=true));await p.locator('[data-field="measurements.ntproBNP"]').fill('2400');await p.locator('[data-field="measurements.ctni"]').fill('0.018');await save(p);await p.locator('[data-act=recheck]').click();assert.equal(await p.locator('[data-field="measurements.ntproBNP"]').inputValue(),'');assert.equal(await p.locator('[data-field="measurements.ctni"]').inputValue(),'');assert.match(await p.locator('[data-prev=ctni]').innerText(),/0.018 ng\/mL/);await p.locator('[data-panel=exam] details').evaluateAll(es=>es.forEach(e=>e.open=true));await p.locator('[data-field="measurements.ntproBNP"]').fill('3200');await p.locator('[data-field="measurements.ctni"]').fill('0.028');await section(p,'compare');assert.match(await p.locator('[data-comparison]').innerText(),/2400[\s\S]*3200\s+\+800/);assert.match(await p.locator('[data-comparison]').innerText(),/0.018[\s\S]*0.028\s+\+0.01/);await save(p);const popup=p.waitForEvent('popup');await p.locator('[data-act=print]').click();const out=await popup;await out.locator('h1').first().waitFor();await out.locator('input[type=checkbox]').first().check();const text=await out.locator('body').innerText();assert.match(text,/NT-proBNP.*pmol\/L.*2400.*3200/s);assert.match(text,/cTnI.*ng\/mL.*0.018.*0.028/s);await out.close();await p.close();});

for(const [condition,key,value] of [['cushing','cortisolACTH','8.2'],['addison','sodium','140'],['hypothyroid','tt4','1.2'],['hyperthyroid','tt4','6.5']])
test('endocrine '+condition+' selection, persistence, fresh recheck, comparison and print',async()=>{
 const p=await page();await begin(p);assert.equal(await p.locator('[data-condition=other]').count(),0);
 await p.locator('[data-condition='+condition+']').check();await p.locator('[data-condition=ckd]').uncheck();
 await p.locator('[data-panel=exam] details').evaluateAll(es=>es.forEach(e=>e.open=true));
 await p.locator('[data-field="measurements.'+key+'"]').fill(value);
 await p.locator('[data-field=endocrineContext]').fill('시험 채혈 12:00 / 투약 08:00');
 await save(p);assert.equal(await p.evaluate(k=>state.records[0].body.chronicChart.measurements[k],key),+value);
 await p.locator('[data-act=recheck]').click();await p.locator('[data-panel=exam] details').evaluateAll(es=>es.forEach(e=>e.open=true));
 assert.equal(await p.locator('[data-field="measurements.'+key+'"]').inputValue(),'');
 assert.equal(await p.locator('[data-field=endocrineContext]').inputValue(),'');
 assert.ok((await p.locator('[data-prev='+key+']').innerText()).includes(value));
 await p.locator('[data-field="measurements.'+key+'"]').fill(String(+value+1));
 await p.locator('[data-field=endocrineContext]').fill('이번 채혈 13:00');
 await save(p);
 const popup=p.waitForEvent('popup');await p.locator('[data-act=print]').click();const out=await popup;await out.locator('h1').first().waitFor();await out.locator('input[type=checkbox]').first().check();
 assert.match(await out.locator('body').innerText(),/이번 채혈 13:00/);await out.close();await p.close();
});
